     1	package br.com.marealta.pousada;
     2	
     3	import br.com.marealta.pousada.domain.*;
     4	import br.com.marealta.pousada.events.EventBus;
     5	import br.com.marealta.pousada.events.ReservationEvent;
     6	import java.math.BigDecimal;
     7	import java.time.LocalDate;
     8	import java.time.YearMonth;
     9	import java.util.ArrayList;
    10	import java.util.Comparator;
    11	import java.util.List;
    12	
    13	public class ReservationService {
    14	    public record NewReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
    15	                                 LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {
    16	    }
    17	
    18	    private final List<Room> rooms;
    19	    private final EventBus events;
    20	    private final List<Reservation> reservations = new ArrayList<>();
    21	
    22	    public ReservationService(List<Room> rooms, EventBus events) {
    23	        this.rooms = List.copyOf(rooms);
    24	        this.events = events;
    25	    }
    26	
    27	    public static List<Room> defaultRooms() {
    28	        return List.of(
    29	                new Room(101, RoomType.STANDARD, 2, new BigDecimal("249.90")),
    30	                new Room(102, RoomType.STANDARD, 2, new BigDecimal("249.90")),
    31	                new Room(201, RoomType.DELUXE, 3, new BigDecimal("389.90")),
    32	                new Room(202, RoomType.DELUXE, 3, new BigDecimal("389.90")),
    33	                new Room(301, RoomType.SUITE, 4, new BigDecimal("579.90")));
    34	    }
    35	
    36	    public List<Room> rooms() {
    37	        return rooms;
    38	    }
    39	
    40	    public synchronized Reservation create(NewReservation n) {
    41	        if (!n.checkOut().isAfter(n.checkIn())) {
    42	            throw invalid("A saída deve ser depois da entrada");
    43	        }
    44	        if (n.guests() < 1) {
    45	            throw invalid("É preciso pelo menos um hóspede");
    46	        }
    47	        Room room = rooms.stream().filter(r -> r.number() == n.roomNumber()).findFirst()
    48	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto não encontrado"));
    49	        if (n.guests() > room.capacity()) {
    50	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    51	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    52	        }
    53	        boolean taken = reservations.stream().anyMatch(r -> r.room().equals(room)
    54	                && r.status() != ReservationStatus.CANCELLED && r.overlaps(n.checkIn(), n.checkOut()));
    55	        if (taken) {
    56	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites");
    57	        }
    58	        Reservation r = new Reservation(reservations.size() + 1, room, n.guestName(), n.guestEmail(),
    59	                n.guestCpf(), n.checkIn(), n.checkOut(), n.guests(), n.ratePlan());
    60	        reservations.add(r);
    61	        return r;
    62	    }
    63	
    64	    public synchronized Reservation get(String id) {
    65	        try {
    66	            int i = Integer.parseInt(id);
    67	            if (i >= 1 && i <= reservations.size()) {
    68	                return reservations.get(i - 1);
    69	            }
    70	        } catch (NumberFormatException ignored) {
    71	            // falls through to not found
    72	        }
    73	        throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva não encontrada");
    74	    }
    75	
    76	    public synchronized Reservation confirm(String id) {
    77	        Reservation r = get(id);
    78	        r.confirm();
    79	        events.publish(new ReservationEvent.Confirmed(r));
    80	        return r;
    81	    }
    82	
    83	    public synchronized Reservation cancel(String id) {
    84	        Reservation r = get(id);
    85	        boolean wasConfirmed = r.status() == ReservationStatus.CONFIRMED;
    86	        r.cancel();
    87	        if (wasConfirmed) {
    88	            events.publish(new ReservationEvent.CancelledAfterConfirmation(r));
    89	        }
    90	        return r;
    91	    }
    92	
    93	    public synchronized Reservation checkIn(String id) {
    94	        Reservation r = get(id);
    95	        r.startStay();
    96	        return r;
    97	    }
    98	
    99	    public synchronized Receipt checkOut(String id) {
   100	        Reservation r = get(id);
   101	        r.endStay();
   102	        return Receipt.of(r);
   103	    }
   104	
   105	    public synchronized Receipt document(String id) {
   106	        Reservation r = get(id);
   107	        if (!r.status().isPaid()) {
   108	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
   109	                    "Segunda via só existe para reserva paga");
   110	        }
   111	        return Receipt.of(r);
   112	    }
   113	
   114	    public synchronized String occupancyCsv(LocalDate night) {
   115	        StringBuilder sb = new StringBuilder("room,type,reservation,check_in,check_out\n");
   116	        List<Reservation> occupying = reservations.stream()
   117	                .filter(r -> r.status().isPaid() && r.occupiesNight(night))
   118	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()))
   119	                .toList();
   120	        for (Reservation r : occupying) {
   121	            sb.append(r.room().number()).append(',').append(r.room().type()).append(',')
   122	                    .append(r.id()).append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
   123	        }
   124	        long rooms = occupying.stream().map(r -> r.room().number()).distinct().count();
   125	        sb.append("total,").append(rooms).append('/').append(this.rooms.size()).append('\n');
   126	        return sb.toString();
   127	    }
   128	
   129	    public synchronized String revenueCsv(YearMonth month) {
   130	        StringBuilder sb = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
   131	        BigDecimal total = Money.ZERO;
   132	        List<Reservation> rows = reservations.stream()
   133	                .filter(r -> YearMonth.from(r.checkIn()).equals(month) && r.netAmount().signum() > 0)
   134	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparingInt(Reservation::id))
   135	                .toList();
   136	        for (Reservation r : rows) {
   137	            sb.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn()).append(',')
   138	                    .append(r.checkOut()).append(',').append(r.status()).append(',')
   139	                    .append(r.netAmount().toPlainString()).append('\n');
   140	            total = Money.round(total.add(r.netAmount()));
   141	        }
   142	        sb.append("total,").append(total.toPlainString()).append('\n');
   143	        return sb.toString();
   144	    }
   145	
   146	    private static ApiException invalid(String message) {
   147	        return new ApiException(400, "INVALID_REQUEST", message);
   148	    }
   149	}
=== events/EventBus.java
     1	package br.com.marealta.pousada.events;
     2	
     3	import java.util.List;
     4	import java.util.concurrent.CopyOnWriteArrayList;
     5	import java.util.logging.Level;
     6	import java.util.logging.Logger;
     7	
     8	public class EventBus {
     9	    private static final Logger LOG = Logger.getLogger(EventBus.class.getName());
    10	    private final List<ReservationListener> listeners = new CopyOnWriteArrayList<>();
    11	
    12	    public void subscribe(ReservationListener listener) {
    13	        listeners.add(listener);
    14	    }
    15	
    16	    public void publish(ReservationEvent event) {
    17	        for (ReservationListener l : listeners) {
    18	            try {
    19	                l.on(event);
    20	            } catch (RuntimeException e) {
    21	                // one failing subscriber must not stop the others nor undo the reservation operation
    22	                LOG.log(Level.SEVERE, "Listener " + l.getClass().getSimpleName() + " failed", e);
    23	            }
    24	        }
    25	    }
    26	}
