     2	
     3	import br.com.marealta.pousada.domain.Money;
     4	import br.com.marealta.pousada.domain.Reservation;
     5	
     6	public class FinanceNotifier implements ReservationListener {
     7	    public static final String ADDRESS = "financeiro@pousadamarealta.com.br";
     8	    private final Outbox outbox;
     9	
    10	    public FinanceNotifier(Outbox outbox) {
    11	        this.outbox = outbox;
    12	    }
    13	
    14	    @Override
    15	    public void on(ReservationEvent event) {
    16	        switch (event) {
    17	            case ReservationEvent.Confirmed(Reservation r) -> outbox.sendEmail(ADDRESS,
    18	                    "Pagamento recebido - reserva " + r.id(),
    19	                    "Pagamento recebido da reserva nº " + r.id() + " (quarto " + r.room().number() + ").\n"
    20	                            + "Valor pago: " + Money.format(r.amountPaid()));
    21	            case ReservationEvent.CancelledAfterConfirmation(Reservation r) -> {
    22	                if (r.refund().signum() > 0) {
    23	                    outbox.sendEmail(ADDRESS,
    24	                            "Reembolso - reserva " + r.id(),
    25	                            "Reserva nº " + r.id() + " cancelada (quarto " + r.room().number() + ").\n"
    26	                                    + "Valor a devolver: " + Money.format(r.refund()));
    27	                }
    28	            }
    29	        }
    30	    }
    31	}
