     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    10	
    11	    private Pricing() {
    12	    }
    13	
    14	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
    15	    }
    16	
    17	    /** High season: December 15 through end of February, and all of July. */
    18	    public static boolean isHighSeason(LocalDate night) {
    19	        Month m = night.getMonth();
    20	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    21	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    22	    }
    23	
    24	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    25	        BigDecimal rate = room.nightlyRate();
    26	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_FACTOR) : rate);
    27	    }
    28	
    29	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    30	        BigDecimal subtotal = Money.ZERO;
    31	        int nights = 0;
    32	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    33	            subtotal = Money.round(subtotal.add(nightPrice(room, d)));
    34	            nights++;
    35	        }
    36	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    37	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    38	                : Money.ZERO;
    39	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    40	    }
    41	}
